/* 1dd2:1e44. Hints on the side's state byte +22 (low, high, middle), on
 * divisions 3-4 holding the group flag, on a division whose commander
 * record has bit 7 of +30, on the third context record's byte +20, then
 * scenario-specific hints (scenario 4; scenario 3 in July-September; any
 * scenario but 1 and 2, worded by the side's stance). */
uint16_t opeu_advice_situational_hint(uint8_t        ds[65536],
                                      const uint8_t* far_text, HostEvent event,
                                      uint16_t sp) {
  LOCALS;
  if (SIDE_BYTE(22) <= 30 && RANDOM(4) == 1) {
    COPY_FAR(TEXT4, opeu_advice_63, 0x0afa);
    SHOW();
    return 1;
  }
  if (SIDE_BYTE(22) >= 50 && RANDOM(4) == 1) {
    COPY_FAR(TEXT4, opeu_advice_64, 0x0b46);
    SHOW();
    return 1;
  }
  if (SIDE_BYTE(22) >= 30 && RANDOM(4) == 1) {
    COPY_FAR(TEXT4, opeu_advice_65, 0x0b79);
    SHOW();
    return 1;
  }
  for (a = 2; a < 4; a++)
    if ((GROUP_FLAGS(CURRENT * 4 + a) & 1) && RANDOM(4) == 1) {
      COPY_FAR(c, opeu_advice_66, 0x0bbf);
      FORMAT1(c, a + 1);
      SHOW();
      return 1;
    }
  for (a = 0; a < 4; a++)
    if ((b = GROUP_RECORD(CURRENT, a)) && (AT(b, 30) & 0x80) &&
        RANDOM(4) == 1) {
      COPY_FAR(c, opeu_advice_67, 0x0bf4);
      FORMAT1(c, a + 1);
      SHOW();
      return 1;
    }
  if (AT(RECORD3, 20) <= 40 && RANDOM(4) == 1) {
    COPY_FAR(c, opeu_advice_68, 0x0c43);
    FORMAT2(c, RECORD3, TEMPLATE(AT(RECORD1, 18), 6));
    SHOW();
    return 1;
  }
  if ((SCENARIO & 0x7f) == 4 && RANDOM(4) == 1) {
    COPY_FAR(TEXT4, opeu_advice_69, 0x0c8a);
    SHOW();
    return 1;
  }
  if ((SCENARIO & 0x7f) == 3 && MONTH >= 7 && MONTH <= 9 && RANDOM(4) == 1) {
    COPY_FAR(TEXT4, opeu_advice_70, 0x0cb2);
    SHOW();
    return 1;
  }
  if ((SCENARIO & 0x7f) != 1 && (SCENARIO & 0x7f) != 2 && RANDOM(6) == 1) {
    if (STANCE(CURRENT) == 1)
      COPY_FAR(TEXT4, opeu_advice_71, 0x0cdb);
    else
      COPY_FAR(TEXT4, opeu_advice_72, 0x0d12);
    SHOW();
    return 1;
  }
  return 0;
}

